contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint v) public {
        c.Initialized(); if (__ESBMC_reverted()) return;
        bool s;
        c.SetMinSum(v); bool __rev0 = __ESBMC_reverted(); if (__rev0) { s = true; } else { s = false; }
        assert(s && c.MinSum() == 0);
    }

    receive() external payable {}
}

